<?php

declare(strict_types=1);

namespace MailjetSDK\DTOs\GetV3;

final class ContactslistIdPathParams extends \Dmorenof\SdkRuntime\DTO
{
    public const array REQUIRED_FIELDS = [
        'list_ID',
    ];

    /**
     * Unique numeric ID assigned to this contact list.
     */
    public int $list_ID;
    /**
     * Unique email address generated by Mailjet for this list. This address which can be used only via Mailjet's SMTP server to reach all contacts in it. It is displayed in the `Address` property of the list. The full email address will be `{list_address}&#64;lists.mailjet.com`. Can be used as an alternative to `list_ID`.
     */
    public string $list_address;

    protected function assignMember(string $name, mixed $value): void
    {
        match ($name) {
            'list_ID' => is_int($value) ? $this->list_ID = $value : parent::assignMember($name, $value),
            'list_address' => is_string($value) ? $this->list_address = $value : parent::assignMember($name, $value),
            default => parent::assignMember($name, $value),
        };
    }
}
